use std::{io::{Read,Write},net::{TcpListener,TcpStream},process::{Command,Child},path::PathBuf,time::{Duration,Instant},os::unix::fs::PermissionsExt};
use serde_json::{json,Value};
#[path="support/director_art.rs"] mod director_art;
const MUTATE:&str="Content-Type: application/json\r\nX-Moro-Request: 1\r\n";
struct Server{child:Child,port:u16,root:PathBuf}
impl Drop for Server{fn drop(&mut self){unsafe{libc::kill(self.child.id() as i32,libc::SIGTERM);}let _=self.child.wait();let _=std::fs::remove_dir_all(&self.root);}}
impl Server{
 fn start()->Self{let port=TcpListener::bind("127.0.0.1:0").unwrap().local_addr().unwrap().port();let root=std::env::temp_dir().join(format!("director-http-{}-{port}",std::process::id()));std::fs::create_dir(&root).unwrap();std::fs::write(root.join("index.html"),"Studio SPA fixture").unwrap();let exe=root.join("fixture");let output=format!("{}\n{}\n",json!({"type":"item.completed","item":{"type":"agent_message","text":proposal().to_string()}}),json!({"type":"turn.completed"}));std::fs::write(root.join("output"),output).unwrap();
 let script=format!("#!/bin/sh\nprintf 'call\\n' >> '{0}/calls'\ncase \" $* \" in *' --help '*) printf '%s' '--ignore-user-config --ignore-rules --output-schema --disable --ephemeral --sandbox --json'; exit 0;; esac\n/bin/cat > '{0}/stdin'\nprintf '%s' \"$$\" > '{0}/pid'\nif test -f '{0}/pause'; then exec /bin/sleep 10; fi\n/bin/cat '{0}/output'\n",root.display());std::fs::write(&exe,script).unwrap();std::fs::set_permissions(&exe,std::fs::Permissions::from_mode(0o700)).unwrap();
 let child=Command::new(env!("CARGO_BIN_EXE_moro-ai-bridge")).args(["--web-root",root.to_str().unwrap(),"--port",&port.to_string(),"--codex-bin",exe.to_str().unwrap(),"--claude-bin","/not-installed"]).env("HOME",&root).env("PATH","").env_remove("CODEX_HOME").env_remove("CLAUDE_CONFIG_DIR").spawn().unwrap();let s=Self{child,port,root};let end=Instant::now()+Duration::from_secs(3);while TcpStream::connect(("127.0.0.1",port)).is_err(){assert!(Instant::now()<end);std::thread::sleep(Duration::from_millis(10));}s
 }
 fn request(&self,method:&str,path:&str,headers:&str,body:&str)->(u16,String){let mut s=TcpStream::connect(("127.0.0.1",self.port)).unwrap();s.set_read_timeout(Some(Duration::from_secs(3))).unwrap();write!(s,"{method} {path} HTTP/1.1\r\nHost: 127.0.0.1:{}\r\nConnection: close\r\nContent-Length: {}\r\n{headers}\r\n{body}",self.port,body.len()).unwrap();let mut out=String::new();s.read_to_string(&mut out).unwrap();(out.split_whitespace().nth(1).unwrap().parse().unwrap(),out)}
 fn submit(&self)->String{let(code,out)=self.request("POST","/api/ai/director/jobs",MUTATE,&request().to_string());assert_eq!(code,202,"{out}");let j=value(&out)["job"].clone();assert_eq!(j["kind"],"director");assert_eq!(j["provider"],"codex");assert_eq!(j["status"],"running");j["id"].as_str().unwrap().into()}
 fn job(&self,id:&str)->Value{let(code,out)=self.request("GET",&format!("/api/ai/jobs/{id}"),"","");assert_eq!(code,200);value(&out)["job"].clone()}
 fn terminal(&self,id:&str)->Value{let end=Instant::now()+Duration::from_secs(4);loop{let j=self.job(id);if j["status"]!="running"{return j;}assert!(Instant::now()<end);std::thread::sleep(Duration::from_millis(10));}}
}
fn value(out:&str)->Value{serde_json::from_str(out.split("\r\n\r\n").nth(1).unwrap()).unwrap()}
fn proposal()->Value{json!({"version":1,"stage":"style","summary":"A badge","review":{"focalPoint":"subject","silhouette":"clear","material":"paper","choreography":"hold","limitations":"review needed"},"poses":[{"frame":0,"label":"style"}],"project":{"version":3,"name":"Local","width":512,"height":512,"fps":60,"durationFrames":120,"layers":director_art::layers()}})}
fn request()->Value{json!({"provider":"codex","prompt":"A badge","consent":true,"stage":"style","approved":null,"contextConsent":false})}
#[test] fn director_http_zero_call_gates_and_context_budget() {
 let s=Server::start();let valid=request();
 for (field,val) in [("consent",json!(false)),("contextConsent",json!(true)),("approved",proposal()),("stage",json!("poses")),("provider",json!("other")),("prompt",json!(" ")),("prompt",json!("🙂".repeat(4001))),("tools",json!([]))] {let mut bad=valid.clone();bad[field]=val;assert_eq!(s.request("POST","/api/ai/director/jobs",MUTATE,&bad.to_string()).0,400,"{field}");}
 for field in ["provider","prompt","consent","stage","approved","contextConsent"]{let mut bad=valid.clone();bad.as_object_mut().unwrap().remove(field);assert_eq!(s.request("POST","/api/ai/director/jobs",MUTATE,&bad.to_string()).0,400,"{field}");}
 for duplicate in [valid.to_string().replacen('{',"{\"consent\":true,",1),valid.to_string().replacen('{',"{\"cont\\u0065xtConsent\":false,",1)]{assert_eq!(s.request("POST","/api/ai/director/jobs",MUTATE,&duplicate).0,400);}
 let mut prior=proposal();prior["summary"]=json!("x".repeat(65537));let large=json!({"provider":"codex","prompt":"x","consent":true,"stage":"poses","contextConsent":true,"approved":prior});let(code,out)=s.request("POST","/api/ai/director/jobs",MUTATE,&large.to_string());assert_eq!(code,400);assert_eq!(value(&out)["error"]["code"],"context_too_large");
 assert_eq!(s.request("POST","/api/ai/director/jobs","Content-Type: application/json\r\n",&valid.to_string()).0,403);assert!(!s.root.join("calls").exists(),"even help must not run on rejected requests");
 let mut missing=valid;missing["provider"]=json!("claude");assert_eq!(s.request("POST","/api/ai/director/jobs",MUTATE,&missing.to_string()).0,503);
}
#[test] fn director_cancel_reaps_and_all_job_kinds_share_one_admission() {
 let s=Server::start();std::fs::write(s.root.join("pause"),"").unwrap();let id=s.submit();let end=Instant::now()+Duration::from_secs(3);while !s.root.join("pid").exists(){assert!(Instant::now()<end);std::thread::sleep(Duration::from_millis(10));}
 for (path,body) in [("/api/ai/director/jobs",request()),("/api/ai/v2/jobs",json!({"provider":"codex","prompt":"x","consent":true})),("/api/ai/jobs",json!({"provider":"codex","prompt":"x"})),("/api/ai/harness/jobs",json!({"provider":"codex","brief":"x","domain":"ui-motion","consent":true,"callBudget":7}))]{let(code,out)=s.request("POST",path,MUTATE,&body.to_string());assert_eq!(code,409,"{out}");assert_eq!(value(&out)["error"]["code"],"busy");}
 assert_eq!(s.request("POST",&format!("/api/ai/jobs/{id}/cancel"),MUTATE,"{}").0,200);let pid:i32=std::fs::read_to_string(s.root.join("pid")).unwrap().parse().unwrap();let end=Instant::now()+Duration::from_secs(3);while unsafe{libc::kill(pid,0)}==0{assert!(Instant::now()<end,"child must be reaped");std::thread::sleep(Duration::from_millis(10));}
 let j=s.terminal(&id);assert_eq!(j["status"],"cancelled");assert_eq!(j["kind"],"director");assert!(j.get("proposal").is_none());std::fs::remove_file(s.root.join("pause")).unwrap();let id=s.submit();assert_eq!(s.terminal(&id)["status"],"succeeded");
}
#[test] fn director_http_success_is_proposal_in_shared_poll_not_project(){let s=Server::start();let id=s.submit();let j=s.terminal(&id);assert_eq!(j["status"],"succeeded","{j}");assert_eq!(j["kind"],"director");assert_eq!(j["proposal"],proposal());assert!(j.get("project").is_none());assert!(j.get("report").is_none());assert_eq!(std::fs::read_to_string(s.root.join("calls")).unwrap().lines().count(),2);for path in ["/studio","/studio/"]{assert_eq!(s.request("GET",path,"","").0,200);} }
